#include <bits/stdc++.h>

using namespace std;

long long n, M, cnt, diff, in, sum = 0, q, r;
long long freq[107];
vector<long long> ans;

void solve() {
    cin >> n >> M;

    for (long long i = 0; i < n; ++i) {
        cin >> in;
        sum += in;
        diff = sum - M;
        cnt = 0;

        if (diff > 0) {
            for (long long j = 100; j > 0; --j) {
                if (diff > 0 && freq[j] > 0) {
                    q = diff / j;
                    r = diff % j;

                    if (q >= freq[j]) {
                        diff -= freq[j] * j;
                        cnt += freq[j];
                    } else {
                        if (r) {
                            ++q;
                        }
                        diff -= j * q;
                        cnt += q;
                    }
                }
            }
        }

        ++freq[in];
        ans.push_back(cnt);
    }

    for (size_t i = 0; i < ans.size(); ++i) {
        if (i > 0) {
            cout << ' ';
        }
        cout << ans[i];
    }
    cout << '\n';
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    solve();
    return 0;
}

